	[10184] = {68, 67, "Malevolent Remnants", nil, nil, nil, nil, nil, nil, {10300}, {10312}, nil, nil, nil, nil, nil, nil, 10312, {68, 12000}, "Custodian Dieworth at Kirin'Var Village wants you to defeat 20 Severed Spirits in Kirin'Var's Town Square."},
