	[10253] = {67, 64, "Levixus the Soul Caller", nil, nil, nil, nil, nil, nil, {10252}, {10164}, nil, nil, nil, nil, nil, nil, 10164, {67, 17450}, "Destroy Levixus and take the Book of the Dead from his possession. Deliver the Book of the Dead to Ramdor the Mad standing outside the Auchenai Crypt entrance of Auchindoun. You had a deal, remember?", {935, 500}},
	[10254] = {60, 55, "Force Commander Danath", 1, nil, nil, nil, nil, nil, {10140}, nil, nil, nil, nil, nil, nil, nil, nil, {60, 955}, "Marshal Isildor wants you to report to Force Commander Danath Trollbane in Honor Hold."},
	[10255] = {63, 61, "Testing the Antidote", nil, nil, nil, nil, nil, nil, {9372}, nil, nil, nil, nil, nil, nil, nil, nil, {63, 10400}, "Use the Cenarion Antidote on a Hulking Helboar and observe the results. Once you have the results of the experiment, return to Thiah Redmane at the Cenarion Post in Hellfire Peninsula.", {942, 250}},
