	[12003] = {75, 73, "Uncovering the Tunnels", 1, nil, nil, nil, nil, nil, {12002}, {12010}, nil, nil, nil, nil, nil, nil, 12010, {75, 20950}, "Brugar Stoneshear at the Westfall Brigade Encampment wants you to explore the North Building, the East Building, and the South Building of Thor Modan."},
	[12004] = {73, 71, "Prevent the Accord", 1, nil, nil, nil, nil, nil, {12000}, nil, nil, nil, nil, nil, nil, nil, nil, {73, 25650}, "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Modera at Stars' Rest.", {1090, 350}},
	[12005] = {73, 71, "Prevent the Accord", 2, nil, nil, nil, nil, nil, {11999}, nil, nil, nil, nil, nil, nil, nil, nil, {73, 25650}, "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", {1090, 350}},
	[12006] = {72, 71, "Avenge this Atrocity!", nil, nil, nil, nil, nil, nil, nil, {12013}, nil, nil, nil, nil, nil, nil, 12013, {72, 20300}, "Kill any combination of 15 Dragonblight Mage Hunters, Moonrest Stalkers, Surge Needle Sorcerers, and Focus Wizards. After you have done that, return to Ethenial Moonshadow at Moonrest Gardens."},
	[12007] = {74, 73, "Sacrifices Must be Made", nil, nil, nil, nil, nil, nil, {11991}, {12042}, nil, nil, nil, nil, nil, nil, 12042, {74, 20750}, "Drakuru wants you to bring the Eye of the Prophets to him at Drakuru's Brazier in Zeb'Halak. You will need to collect Zim'bo's Mojo to use Drakuru's Elixir there."},
	[12008] = {72, 71, "Agmar's Hammer", 2, nil, nil, nil, nil, nil, {11983}, {12034}, nil, nil, nil, nil, nil, nil, 12034, {72, 15250}, "Travel to Agmar's Hammer in the Dragonblight and speak to Overlord Agmar.", {1085, 150}},
	[12009] = {72, 71, "Tua'kea's Crab Traps", nil, nil, nil, nil, nil, nil, {11959}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Collect 8 of Tua'kea's Crab Traps and return them to him at Moa'ki Harbor.", {1073, 250}},
	[12010] = {75, 73, "The Fate of Orlond", 1, nil, nil, nil, nil, nil, {12003}, {12014}, nil, nil, nil, nil, nil, nil, 12014, {75, 15700}, "Locate Surveyor Orlond within Thor Modan."},
	[12011] = {72, 71, "Signs of Big Watery Trouble", nil, nil, nil, nil, nil, nil, {11959}, {12016}, nil, nil, nil, nil, nil, nil, 12016, {72, 2050}, "Inform Tua'kea at Moa'ki Harbor about the wrecked crab trap.", {1073, 10}},
	[12013] = {73, 71, "End Arcanimus", nil, nil, nil, nil, nil, nil, {12006}, nil, nil, nil, nil, nil, nil, nil, nil, {73, 25650}, "Destroy Arcanimus and then return to Ethenial Moonshadow at Moonrest Gardens."},
	[12014] = {75, 73, "Steady as a Rock?", 1, nil, nil, nil, nil, nil, {12010}, nil, nil, nil, nil, nil, nil, nil, nil, {75, 26200}, "Retreive the Portable Seismograph and use it to take stability readings in Thor Modan, then return to Brugar Stoneshear at the Westfall Brigade Encampment."},
	[12016] = {72, 71, "The Bait", nil, nil, nil, nil, nil, nil, {12011}, {12017}, nil, nil, nil, nil, nil, nil, 12017, {72, 20300}, "Obtain The Flesh of \"Two Huge Pincers\" and deliver it to Tua'kea at Moa'ki Harbor.", {1073, 250}},
	[12017] = {73, 71, "Meat on the Hook", nil, nil, nil, nil, nil, nil, {12016}, nil, nil, nil, nil, nil, nil, nil, nil, {73, 25650}, "Slay Tu'u'gwar and then return to Tua'kea at Moa'ki Harbor.", {1073, 350}},
	[12019] = {72, 68, "Last Rites", 1, nil, nil, nil, nil, nil, {11942}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 30450}, "Go to the Temple City of En'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar. Use it to reach the top and help Thassarian there.", {1050, 500}},
	[12026] = {75, 73, "The Damaged Journal", 2, nil, nil, nil, nil, nil, nil, {12054}, nil, nil, nil, nil, nil, nil, 12054, {75, 20950}, "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Sage Paluna at Camp Oneqwah.", {1064, 250}},
	[12027] = {74, 73, "Mr. Floppy's Perilous Adventure", 1, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter."},
	[12028] = {72, 71, "Spiritual Insight", nil, nil, nil, nil, nil, nil, {11959}, {12030}, nil, nil, nil, nil, nil, nil, 12030, {72, 20300}, "Speak with Toalu'u the Mystic at Moa'ki Harbor after you have attained your spiritual insight.", {1073, 250}},
	[12029] = {74, 73, "Seared Scourge", nil, nil, nil, nil, nil, nil, {12484}, {12037}, nil, nil, nil, nil, nil, nil, 12037, {74, 20750}, "Mack at Granite Springs wants you to use his grog to burn 20 Famished Scourge Trolls at Drak'Tharon."},
	[12030] = {72, 71, "Elder Mana'loa", nil, nil, nil, nil, nil, nil, {12028}, {12031}, nil, nil, nil, nil, nil, nil, 12031, {72, 20300}, "Speak with the statue, Elder Mana'loa, at Indu'le Village.", {1073, 250}},
	[12031] = {72, 71, "Freedom for the Lingering", nil, nil, nil, nil, nil, nil, {12030}, {12032}, nil, nil, nil, nil, nil, nil, 12032, {72, 20300}, "Put to rest any combination of 15 Indu'le Fishermen, Mystics and Warriors, then return to Elder Mana'loa at Indu'le Village.", {1073, 250}},
	[12032] = {72, 71, "Conversing With the Depths", nil, nil, nil, nil, nil, nil, {12031}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 25400}, "Commune with The Pearl of the Depths and do as the sea-goddess Oacha'noa instructs. Should you survive the ordeal, return to Toalu'u the Mystic at Moa'ki Harbor.", {1073, 500}},
	[12033] = {72, 71, "Message from the West", 2, nil, nil, nil, nil, nil, {11916}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 15250}, "Read the Letter from Saurfang and then destroy it. Speak to Messenger Torvus once you have completed this task.", {1085, 150}},
	[12034] = {72, 71, "Victory Nears...", 2, nil, nil, nil, nil, nil, {12008}, {12036}, nil, nil, nil, nil, nil, nil, 12036, {72, 2050}, "Speak to Senior Sergeant Juktok at Agmar's Hammer.", {1085, 10}},
	[12035] = {71, 68, "Repurposed Technology", 1, nil, nil, nil, nil, nil, {11908}, nil, nil, nil, nil, nil, nil, nil, nil, {71, 20100}, "Jeremiah Hawning at Farshire wants you to destroy 5 Harvest Collectors and then use Jeremiah's Tools to rewire them.", {1050, 250}},
	[12036] = {72, 71, "From the Depths of Azjol-Nerub", 2, nil, nil, nil, nil, nil, {12034}, {12053}, nil, nil, nil, nil, nil, nil, 12053, {72, 20300}, "Explore the Pit of Narjun and return with your findings to Senior Sergeant Juktok at Agmar's Hammer.", {1085, 250}},
	[12037] = {74, 72, "Search and Rescue", nil, nil, nil, nil, nil, nil, {12029}, {13129}, nil, nil, nil, nil, nil, nil, 13129, {74, 41500}, "Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel."},
	[12038] = {72, 70, "Seared Scourge", nil, 2, nil, nil, nil, nil, {12029}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Mack at Granite Springs wants you to use his grog to burn 30 Famished Scourge Trolls."},
	[12039] = {72, 71, "Black Blood of Yogg-Saron", 2, nil, nil, nil, nil, nil, {12034}, {12048}, nil, nil, nil, nil, nil, nil, 12048, {72, 20300}, "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to recover 10 Black Blood of Yogg-Saron Samples.", {1085, 250}},
	[12040] = {72, 71, "An Enemy in Arthas", 2, nil, nil, nil, nil, nil, nil, {12041}, nil, nil, nil, nil, nil, nil, 12041, {72, 20300}, "Kilix the Unraveler at the Pit of Narjun in the Dragonblight has asked that you slay 6 Anub'ar Underlords."},
	[12041] = {72, 71, "The Lost Empire", nil, nil, nil, nil, nil, nil, {12040}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 15250}, "Deliver Kilix's Battle Plan to Overlord Agmar at Agmar's Hammer to the east.", {1052, 150}},
	[12042] = {74, 73, "Heart of the Ancients", nil, nil, nil, nil, nil, nil, {12007}, {12802}, nil, nil, nil, nil, nil, nil, 12802, {74, 20750}, "Drakuru wants you to go to the uppermost chamber at Blue Sky Logging Ground and find the Heart of the Ancients."},
	[12043] = {74, 72, "Nozzlerust Defense", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Kill 12 Wastes Diggers and 1 Wastes Taskmaster at the digs surrounding Galakrond's Rest. Return to Narf at Nozzlerust Post when the task is complete."},
	[12044] = {74, 72, "Stocking Up", nil, nil, nil, nil, nil, nil, {12469}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Gather 8 bundles of Composite Ore from the digs surrounding Galakrond's Rest and bring them to Xink at Nozzlerust Post."},
	[12045] = {74, 72, "Shaved Ice", nil, nil, nil, nil, nil, nil, nil, {12046}, nil, nil, nil, nil, nil, nil, 12046, {74, 20750}, "Collect 4 Ice Shard Clusters from Ice Elementals in the north and bring them to Zivlix at Nozzlerust Post."},
	[12046] = {74, 72, "Soft Packaging", nil, nil, nil, nil, nil, nil, {12045}, {12047}, nil, nil, nil, nil, nil, nil, 12047, {74, 20750}, "Collect 12 Thin Animal Hides from the Jormungar Tunnelers or the Dragonbone Condors near Nozzlerust Post. Once you've located the hides, return them to Zivlix."},
	[12047] = {74, 72, "Something That Doesn't Melt", nil, nil, nil, nil, nil, nil, {12046}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Search the dragon bones east of Nozzlerust Post for 12 Splintered Bone Chunks."},
	[12048] = {72, 71, "Scourge Armaments", 2, nil, nil, nil, nil, nil, {12039}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to bring him 8 Scourge Armaments.", {1085, 250}},
	[12049] = {74, 72, "Hard to Swallow", nil, nil, nil, nil, nil, nil, {12046}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Battle a Hulking Jormungar east of Nozzlerust Post until it opens its mouth, then throw a Potent Explosive Charge into its throat. After it explodes, collect 6 slabs of Seared Jormungar Meat off of the ground and bring them back to Xink."},
	[12050] = {74, 72, "Lumber Hack", nil, nil, nil, nil, nil, {12046, 12047}, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Use Xink's Shredder Control Device to call a Shredder once you reach the Harpy Nesting Grounds in the North. Gather 50 Bundles of Lumber from the trees in the area, and then return to Xink at Nozzlerust Post. Should you lose Xink's Shredder Control Device, speak to Xink at Nozzlerust Post to obtain a new one."},
	[12052] = {74, 72, "Harp on This!", nil, nil, nil, nil, nil, {12046, 12047}, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 25950}, "Kill the Mistress of the Coldwind and 15 Coldwind harpies in the mountains northwest of Nozzlerust Post. Return to Narf once the task is complete. Should you be in need of Xink's Shredder Control Device, speak to Xink at Nozzlerust Post."},
	[12053] = {72, 71, "The Might of the Horde", 2, nil, nil, nil, nil, nil, {12036}, {12071}, nil, nil, nil, nil, nil, nil, 12071, {72, 20300}, "Senior Sergeant Juktok at Agmar's Hammer in the Dragonblight wants you to use the Warsong Battle Standard at Icemist Village and defend it against attackers. Return the Warsong Battle Standard when you are finished.", {1085, 250}},
	[12054] = {75, 73, "Deciphering the Journal", 2, nil, nil, nil, nil, nil, {12026}, nil, nil, nil, nil, nil, nil, nil, nil, {75, 20950}, "Bring a sprig of Spiritsbreath to Sage Paluna at Camp Oneqwah.", {1064, 250}},
	[12055] = {72, 71, "A Strange Device", 1, nil, nil, nil, nil, nil, {12000}, {12060}, nil, nil, nil, nil, nil, nil, 12060, {72, 10150}, "Deliver Goramosh's Strange Device to the Image of Archmage Modera at Stars' Rest.", {1090, 75}},
	[12056] = {72, 71, "Marked for Death: High Cultist Zangus", 2, nil, nil, nil, nil, nil, {12034}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Kill High Cultist Zangus and return High Cultist Zangus's Head to Captain Gort at Agmar's Hammer in the Dragonblight.", {1085, 250}},
	[12057] = {72, 71, "The Flesh-Bound Tome", 2, nil, nil, nil, nil, nil, nil, {12115}, nil, nil, nil, nil, nil, nil, 12115, {72, 20300}, "Return the Flesh-bound Tome to Captain Gort at Agmar's Hammer.", {1085, 250}},
	[12058] = {75, 73, "The Runic Prophecies", 2, nil, nil, nil, nil, nil, {12054}, nil, nil, nil, nil, nil, nil, nil, nil, {75, 20950}, "Sage Paluna at Camp Oneqwah wants you to decipher the three Rune Plates.", {1064, 250}},
	[12059] = {72, 71, "A Strange Device", 2, nil, nil, nil, nil, nil, {11999}, {12061}, nil, nil, nil, nil, nil, nil, 12061, {72, 10150}, "Deliver Goramosh's Strange Device to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", {1090, 75}},
	[12060] = {72, 71, "Projections and Plans", 1, nil, nil, nil, nil, nil, {12055}, {12061, 12065}, nil, nil, nil, nil, nil, nil, 12065, {72, 20300}, "Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens. Afterward, return to the Image of Archmage Modera at Stars' Rest with the information.", {1090, 250}},
	[12061] = {72, 71, "Projections and Plans", 2, nil, nil, nil, nil, nil, {12059}, {12060, 12066}, nil, nil, nil, nil, nil, nil, 12066, {72, 20300}, "Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens. Afterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer with the information.", {1090, 250}},
	[12063] = {72, 71, "Strength of Icemist", 2, nil, nil, nil, nil, nil, {12036}, {12064}, nil, nil, nil, nil, nil, nil, 12064, {72, 15250}, "Find Banthok Icemist at Icemist Village.", {1052, 150, 1064, 150}},
	[12064] = {72, 71, "Chains of the Anub'ar", 2, nil, nil, nil, nil, nil, {12063}, {12069}, nil, nil, nil, nil, nil, nil, 12069, {72, 20300}, "Banthok Icemist at Icemist Village in the Dragonblight has asked that you bring him Anok'ra's Key Fragment, Tivax's Key Fragment and Sinok's Key Fragment.", {1052, 250, 1064, 250}},
	[12065] = {72, 71, "The Focus on the Beach", 1, nil, nil, nil, nil, nil, {12060}, {12066, 12083}, nil, nil, nil, nil, nil, nil, 12083, {72, 20300}, "Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand. Then, return to the Image of Archmage Modera at Stars' Rest.", {1090, 250}},
	[12066] = {72, 71, "The Focus on the Beach", 2, nil, nil, nil, nil, nil, {12061}, {12065, 12084}, nil, nil, nil, nil, nil, nil, 12084, {72, 20300}, "Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand. Then, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", {1090, 250}},
	[12067] = {72, 71, "A Letter for Home", 1, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Deliver Captain Malin's Letter to Commander Saia Azuresteel at Stars' Rest.", {1050, 250}},
	[12068] = {75, 73, "Voices From the Dust", nil, nil, nil, nil, nil, nil, {12802}, {12238}, nil, nil, nil, nil, nil, nil, 12238, {75, 20950}, "Drakuru wants you to collect the Drakkari Tablets from the Ruins of Drakil'jin and 5 Sacred Mojo from Drakkari Oracles and Protectors there. You are then to use Drakuru's Elixir at Drakuru's Brazier at the ruins to summon his image."},
	[12069] = {73, 71, "Return of the High Chief", 2, nil, nil, nil, nil, nil, {12064}, {12140}, nil, nil, nil, nil, nil, nil, 12140, {73, 30750}, "Free High Chief Icemist using the Anub'ar Prison Key and assist him in defeating Under-king Anub'et'kan. Recover a Fragment of Anub'et'kan's Husk and return it to Overlord Agmar at Agmar's Hammer in the Dragonblight.", {1052, 500, 1064, 500}},
	[12070] = {75, 72, "Rallying the Troops", nil, nil, nil, nil, nil, nil, {11982}, {11985}, nil, nil, nil, nil, nil, nil, 11985, {75, 20950}, "Use the Shard of the Earth to rally the Grizzly Hills Giants fighting in the Boulder Hills, kill any iron dwarves who oppose you, then report to Kurun on the hill overlooking Thor Modan."},
	[12071] = {72, 71, "Attack by Air!", 2, nil, nil, nil, nil, nil, {12053}, {12072}, nil, nil, nil, nil, nil, nil, 12072, {72, 2050}, "Speak with Valnok Windrager at Agmar's Hammer.", {1085, 10}},
	[12072] = {72, 71, "Blightbeasts be Damned!", 2, nil, nil, nil, nil, nil, {12071}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Use Valnok's Flare Gun to call down a Kor'kron War Rider at Icemist Village. Mount the Kor'kron War Rider and then use it to kill 25 Anub'ar Blightbeasts! Return to Valnok Windrager at Agmar's Hammer should you complete this mission.", {1085, 250}},
	[12073] = {75, 73, "Pounding the Iron", 2, nil, nil, nil, nil, nil, {12054}, nil, nil, nil, nil, nil, nil, nil, nil, {75, 20950}, "Kill any 10 Iron Dwarves defending Thor Modan and report back to Scout Vor'takh at Camp Oneqwah.", {1085, 250}},
	[12074] = {75, 73, "An Expedient Ally", 2, nil, nil, nil, nil, nil, nil, {11981}, nil, nil, nil, nil, nil, nil, nil, {75, 2100}, "Speak with Kurun on the hill overlooking Thor Modan."},
	[12075] = {74, 72, "Slim Pickings", nil, nil, nil, nil, nil, nil, nil, {12076}, nil, nil, nil, nil, nil, nil, 12076, {74, 20750}, "Collect a sample of Rockflesh from the Ice Giant corpse at the cavern entrance in the Crystal Vice, north of Zort's location. After this task is complete, return to Zort near the center of the canyon."},
	[12076] = {74, 72, "Messy Business", nil, nil, nil, nil, nil, nil, {12075}, {12077}, nil, nil, nil, nil, nil, nil, 12077, {74, 20750}, "Collect 2 Vials of Corrosive Spit from the Jormungar by using the scraper on yourself. Bring the vials back to Zort in the Crystal Vice when your task is complete."},
	[12077] = {74, 72, "Apply This Twice A Day", nil, nil, nil, nil, nil, nil, {12076}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Offer the elixir that Zort has prepared to Ko'char the Unbreakable."},
	[12078] = {74, 72, "Worm Wrangler", nil, nil, nil, nil, nil, nil, {12077}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Enter the caverns in Crystal Vice and trap 3 Jormungar Spawn inside sturdy crates. Be sure to pick the crates up after the Jormungar Spawn are trapped inside! Bring the captured Jormungar Spawn back to Zort in the Crystal Vice."},
	[12079] = {74, 72, "Stomping Grounds", nil, nil, nil, nil, nil, nil, {12075}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 20750}, "Delve into the cavern at the north end of the Crystal Vice and kill 8 Ice Heart Jormungar Feeders for Ko'char the Unbreakable."},
	[12080] = {74, 72, "Really Big Worm", nil, nil, nil, nil, nil, nil, {12076}, nil, nil, nil, nil, nil, nil, nil, nil, {74, 31150}, "Enter the Ice Heart Cavern and slay Rattlebore. If it is still in your possession, be sure to use Zort's Protective Elixir to protect you from the Jormungar's corrosive spit. Return to Ko'char the Unbreakable in the Crystal Vice when the task is complete."},
	[12081] = {75, 72, "Gavrock", nil, nil, nil, nil, nil, nil, {11985}, {12093}, nil, nil, nil, nil, nil, nil, 12093, {75, 2100}, "Speak with Gavrock at the Ruins of Tethys."},
	[12082] = {75, 73, "Dun-da-Dun-tah!", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {75, 20950}, "Escort Harrison from Drakil'jin Ruins, then speak with Harkor at Harkor's Camp."},
	[12083] = {72, 71, "Atop the Woodlands", 1, nil, nil, nil, nil, nil, {12065}, {12084, 12098}, nil, nil, nil, nil, nil, nil, 12098, {72, 20300}, "Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands. Then, return to the Image of Archmage Modera at Stars' Rest.", {1090, 250}},
	[12084] = {72, 71, "Atop the Woodlands", 2, nil, nil, nil, nil, nil, {12066}, {12083, 12106}, nil, nil, nil, nil, nil, nil, 12106, {72, 20300}, "Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands. Then, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", {1090, 250}},
	[12085] = {72, 71, "A Letter for Home", 2, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Deliver Lieutenant Ta'zinni's Letter to Overlord Agmar at Agmar's Hammer.", {1085, 250}},
	[12086] = {72, 68, "The Son of Karkut", 1, nil, nil, nil, nil, nil, {11932}, {11944}, nil, nil, nil, nil, nil, nil, 11944, {72, 20300}, "Go east to Death's Stand, just beyond Unu'pe.", {1050, 250}},
	[12088] = {72, 68, "Thassarian, the Death Knight", 1, nil, nil, nil, nil, nil, {11944}, {11956}, nil, nil, nil, nil, nil, nil, 11956, {72, 5100}, "Look for Thassarian inside the Wailing Ziggurat, north of Death's Stand.", {1050, 25}},
	[12089] = {74, 71, "Wanted: Magister Keldonus", 2, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 25950}, "Slay Magister Keldonus and return to Captain Gort at Agmar's Hammer in the Dragonblight.", {1085, 350}},
	[12090] = {74, 71, "Wanted: Gigantaur", 2, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 25950}, "Slay Gigantaur and return to Captain Gort at Agmar's Hammer in the Dragonblight.", {1052, 350}},
	[12091] = {74, 71, "Wanted: Dreadtalon", 2, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {74, 25950}, "Slay Dreadtalon and return to Captain Gort at Agmar's Hammer in the Dragonblight.", {1085, 350}},
	[12092] = {72, 71, "Strengthen the Ancients", 1, nil, nil, nil, nil, nil, {12065}, nil, nil, nil, nil, nil, nil, nil, nil, {72, 20300}, "Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Sarendryana at Stars' Rest.", {1050, 250}},
