	[12640] = {77, 74, "Sealing the Rifts", nil, nil, nil, nil, nil, nil, {12622}, {12659}, nil, nil, nil, nil, nil, nil, 12659, {77, 21400}, "Scalper Ahunae at Zim'Torga has asked you to seal 7 Elemental Rifts."},
	[12641] = {55, 55, "Death Comes From On High", nil, nil, nil, nil, 32, nil, {12636}, {12657}, nil, nil, nil, nil, nil, nil, 12657, {55, 12250}, "The Lich King commands you to use the Eye of Acherus to analyze the Scarlet Hold, New Avalon Forge, New Avalon Town Hall and the Chapel of the Crimson Flame. Control the Eye of Acherus by using the Eye of Acherus Control Mechanism."},
	[12642] = {77, 74, "Spirit of Rhunok", nil, nil, nil, nil, nil, nil, {12632}, {12646}, nil, nil, nil, nil, nil, nil, 12646, {77, 10700}, "Speak with the Spirit of Rhunok at the Altar of Rhunok."},
