	[12652] = {75, 74, "Feedin' Da Goolz", nil, nil, nil, nil, nil, nil, {12629, 12643}, {12713}, nil, nil, nil, nil, nil, nil, nil, {75, 20950}, "Gristlegut at the Reliquary of Agony wants you to use Bowels and Brains Bowl next to 10 Decaying Ghouls."},
	[12653] = {77, 74, "Back to Har'koa", nil, nil, nil, nil, nil, nil, {12647}, {12665}, nil, nil, nil, nil, nil, nil, 12665, {77, 10700}, "Speak with Har'koa at the Altar of Har'koa."},
	[12654] = {76, 76, "The Part-time Hunter", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {76, 21150}, "Bring Pitch's Remains to Tamara Wobblesprocket at Lakeside Landing."},
	[12655] = {77, 74, "The Blessing of Zim'Rhuk", nil, nil, nil, nil, nil, nil, {12632}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Witch Doctor Khufu wants you to present 10 Drakkari Offerings to the statue of Zim'Rhuk."},
	[12656] = {77, 74, "Blessing of Zim'Rhuk", nil, nil, nil, nil, nil, nil, {12655}},
	[12657] = {55, 55, "The Might Of The Scourge", nil, nil, nil, nil, 32, nil, {12641}, {12850}, nil, nil, nil, nil, nil, nil, 12850, {55, 12250}, "The Lich King commands you to carry his orders to Highlord Darion Mograine at Ebon Hold. Use the glowing transporter behind the Lich King to reach Highlord Darion Mograine in the Hall of Command."},
	[12658] = {77, 76, "My Pet Roc", nil, nil, nil, nil, nil, nil, {12603}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Bring 7 Roc Eggs to Zootfizzle at Dorian's Outpost."},
	[12659] = {77, 74, "Scalps!", nil, nil, nil, nil, nil, nil, {12640}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Scalper Ahunae at Zim'Torga wants you to use Ahunae's Knife to scalp 10 Heb'Drakkar trolls. The scalper reminds you that you should loot them first."},
	[12660] = {77, 77, "Weapons of Destruction", nil, nil, nil, nil, nil, nil, {12608}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "The Avatar of Freya wants you to go to the Death's Hand Encampment to the northwest and destroy 4 Unstable Explosives."},
	[12661] = {75, 74, "Infiltrating Voltarus", nil, nil, nil, nil, nil, nil, {12648, 12649}, {12669}, nil, nil, nil, nil, nil, nil, 12669, {75, 20950}, "Stefan wants you to use your Ensorcelled Choker to get into Voltarus and do whatever the Scourge leader there asks of you. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", {1098, 250}},
	[12662] = {77, 74, "Bringing Down Heb'Jin", nil, nil, nil, nil, nil, nil, {12640}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Element-Tamer Dagoda at Zim'Torga wants you to kill Heb'Jin."},
	[12663] = {75, 74, "Reunited", nil, nil, nil, nil, nil, nil, {12649}, {12648, 12664}, nil, nil, nil, nil, nil, 12661, nil, nil, "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak."},
	[12664] = {75, 74, "Dark Horizon", nil, nil, nil, nil, nil, nil, {12648}, {12649, 12663}, nil, nil, nil, nil, nil, 12661, nil, nil, "Drakuru in Voltarus wants you to speak to Gorebag and take the tour of Zul'Drak."},
	[12665] = {77, 74, "I Sense a Disturbance", nil, nil, nil, nil, nil, nil, {12653}, {12666}, nil, nil, nil, nil, nil, nil, 12666, {77, 21400}, "Har'koa has asked you to determine what has happened to Quetz'lun. Speak to her to be able to ride one of her children stealthily into the Altar of Quetz'lun. Return to her at the Altar of Har'koa once you have done so."},
	[12666] = {77, 74, "Preparations for the Underworld", nil, nil, nil, nil, nil, nil, {12665}, {12667}, nil, nil, nil, nil, nil, nil, 12667, {77, 21400}, "Har'koa wants you to collect 8 Sacred Adornments. Deliver them to her at the Altar of Har'koa."},
	[12667] = {77, 74, "Seek the Wind Serpent Goddess", nil, nil, nil, nil, nil, nil, {12666}, {12672}, nil, nil, nil, nil, nil, nil, 12672, {77, 10700}, "Seek Quetz'lun's Spirit at the Altar of Quetz'lun."},
	[12668] = {77, 74, "Foundation for Revenge", nil, nil, nil, nil, nil, nil, {12672}, {12674}, nil, nil, nil, nil, nil, nil, 12674, {77, 21400}, "Quetz'lun's Spirit has tasked you with the destruction of 12 trolls, either Quetz'lun Worshippers or Serpent-Touched Berserkers, near her Soul Fonts. Only after you have accomplished this should you return to her at the Altar of Quetz'lun."},
	[12669] = {75, 74, "So Far, So Bad", nil, nil, nil, nil, nil, nil, {12661}, {12677}, nil, nil, nil, nil, nil, nil, 12677, {75, 20950}, "Stefan at Ebon Watch wants you to return to Drakuru and complete any tasks he has for you. While at the Reliquary of Pain, you are to use the Diluting Additive on 5 Blight Cauldrons. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", {1098, 250}},
	[12670] = {55, 55, "The Scarlet Harvest", nil, nil, nil, nil, 32, nil, {12850}, {12678}, nil, nil, nil, nil, nil, nil, 12678, {55, 815}, "Report to Prince Valanar at Death's Breach."},
	[12671] = {77, 77, "Reconnaissance Flight", nil, nil, nil, nil, nil, nil, {12699}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Help Pilot Vic complete the Reconnaissance Flight."},
	[12672] = {77, 74, "Setting the Stage", nil, nil, nil, nil, nil, nil, {12667}, {12668}, nil, nil, nil, nil, nil, nil, 12668, {77, 21400}, "Quetz'lun's Spirit has demanded that you collect 10 Underworld Power Fragments. Return to her at the Altar of Quetz'lun only when you have done so."},
	[12673] = {75, 74, "It Rolls Downhill", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, 12669, nil, {75, 20950}, "Overlord Drakuru in Voltarus wants you to use the Scepter of Suggestion on the Blight Geists and then order them to harvest 7 Blight Crystals."},
	[12674] = {77, 74, "Hell Hath a Fury", nil, nil, nil, nil, nil, nil, {12668}, {12675}, nil, nil, nil, nil, nil, nil, 12675, {77, 26750}, "Quetz'lun's Spirit at the Altar of Quetz'lun wants you to use Quetz'lun's Hexxing Stick upon High Priest Mu'funu, High Priestess Tua-Tua, and High Priest Hawinni. Once you have done this, slay them."},
	[12675] = {77, 74, "One Last Thing", nil, nil, nil, nil, nil, nil, {12674}, {12684}, nil, nil, nil, nil, nil, nil, 12684, {77, 10700}, "Deliver the Underworld Power Fragments to Har'koa and beseech her for a portion of her spirit. You will still find her at the Altar of Har'koa."},
	[12676] = {75, 74, "Sabotage", nil, nil, nil, nil, nil, nil, {12677}, {12713}, nil, nil, nil, nil, nil, nil, 12713, {75, 20950}, "Stefan at Ebon Watch wants you to perform another task for Drakuru. Additionally, you are to use the Explosive Charges on 5 Scourgewagons at the Reliquary of Pain. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", {1098, 250}},
	[12677] = {75, 74, "Hazardous Materials", nil, nil, nil, nil, nil, nil, {12669}, {12676}, nil, nil, nil, nil, nil, nil, 12676, {75, 20950}, "Stefan at Ebon Watch wants you to go to Voltarus and complete any tasks Drakuru has for you. While there, you are to steal 5 Harvested Blight Crystals. If you lose your Ensorcelled Choker, return to Stefan at Ebon Watch to get another.", {1098, 250}},
	[12678] = {55, 55, "If Chaos Drives, Let Suffering Hold The Reins", nil, nil, nil, nil, 32, nil, {12670}, nil, nil, nil, nil, nil, nil, nil, nil, {55, 12250}, "Prince Valanar at Death's Breach commands you to slay 10 Scarlet Crusaders or Scarlet Peasants and 10 Citizens of Havenshire."},
	[12679] = {55, 55, "Tonight We Dine In Havenshire", nil, nil, nil, nil, 32, nil, {12670}, nil, nil, nil, nil, nil, nil, nil, nil, {55, 12250}, "Orithos the Sky Darkener at Death's Breach wants you to recover 15 Saronite Arrows."},
	[12680] = {55, 55, "Grand Theft Palomino", nil, nil, nil, nil, 32, nil, {12670}, {12687}, nil, nil, nil, nil, nil, nil, 12687, {55, 12250}, "Salanar the Horseman asks that you steal a horse from the Havenshire Stables and return it to him at Death's Breach."},
	[12681] = {77, 76, "Reagent Agent", nil, nil, nil, nil, nil, nil, {12603}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Bring 5 Twisted Roc Claws to Colvin Norrington at Dorian's Outpost."},
	[12683] = {77, 76, "Burning to Help", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Colvin Norrington at Dorian's Outpost wants you to take 5 Hydra Sputum Samples and kill 5 Bittertide Hydra."},
	[12684] = {77, 74, "Blood of a Dead God", nil, nil, nil, nil, nil, nil, {12675}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Har'koa has asked you to collect 7 Blood of Mam'toth. Return them to her at the Altar of Har'koa."},
	[12685] = {77, 74, "You Reap What You Sow", nil, nil, nil, nil, nil, nil, {12684}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 26750}, "Slay the Drained Prophet of Quetz'lun and then inform Witch Doctor Khufu at Zim'Torga."},
	[12686] = {75, 74, "Zero Tolerance", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, 12677, nil, {75, 10500}, "Drakuru in Voltarus wants you to go to the Reliquary of Pain and use the Scepter of Empowerment on a Servant of Drakuru. You are then to use its abilities to defeat Darmuk."},
	[12687] = {55, 55, "Into the Realm of Shadows", nil, nil, nil, nil, 32, nil, {12680}, nil, nil, nil, nil, nil, nil, nil, nil, {55, 16340}, "Salanar the Horseman at Death's Breach has challenged you to slay the Dark Rider of Acherus and take his Acherus Deathcharger. Should you succeed, return the Acherus Deathcharger to Death's Breach and use the Horseman's Call to summon Salanar."},
	[12688] = {76, 76, "Engineering a Disaster", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {76, 21150}, "Help Engineer Helice escape from Swindlegrin's Dig, then speak with Hemet Nesingwary at the Nesingwary Base Camp."},
	[12689] = {77, 76, "Hand of the Oracles", nil, 2, nil, nil, nil, nil, {12581}, {12582}, nil, nil, nil, nil, nil, nil, nil, {77, 10700}},
	[12690] = {75, 74, "Fuel for the Fire", nil, nil, nil, nil, nil, nil, nil, {12710}, nil, nil, nil, nil, nil, 12676, 12710, {75, 20950}, "Drakuru in Voltarus wants you to use the Scepter of Command on Bloated Abominations and then use their abilities at the Frigid Breach to kill 60 Drakkari Skullcrushers and lure out 3 Drakkari Chieftains. Chieftains will appear when enough Skullcrushers have been slain."},
	[12691] = {78, 77, "A Timeworn Coffer", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {78, 21600}, "Obtain a Huge Stone Key from the nearby Sholazar Guardians and bring it to the Timeworn Coffer at the Maker's Overlook."},
	[12692] = {77, 76, "Return of the Lich Hunter", nil, nil, nil, nil, nil, nil, {12582}, nil, nil, nil, {1104, 9000}, nil, nil, nil, nil, {77, 10700}, "Return to Frenzyheart Hill and speak to Elder Harkek."},
	[12695] = {77, 76, "Return of the Friendly Dryskin", nil, nil, nil, nil, nil, nil, {12689}, nil, nil, nil, {1105, 9000}, nil, nil, nil, nil, {77, 10700}, "Return to Rainspeaker Canopy and speak to High-Oracle Soo-say."},
	[12696] = {77, 77, "Aerial Surveillance", nil, nil, nil, nil, nil, nil, {12523}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 5350}, "Professor Calvert wants you to take the flight to Lakeside Landing and speak with Pilot Vic there."},
	[12697] = {55, 55, "Gothik the Harvester", nil, nil, nil, nil, 32, {12678, 12679, 12687, 12733}, nil, {12698}, nil, nil, nil, nil, nil, nil, 12698, {55, 815}, "Speak with Gothik the Harvester at Death's Breach."},
	[12698] = {55, 55, "The Gift That Keeps On Giving", nil, nil, nil, nil, 32, nil, {12697}, {12700}, nil, nil, nil, nil, nil, nil, 12700, {55, 12250}, "Gothik the Harvester at Death's Breach has given you the Gift of the Harvester to use on Scarlet Miners. Create 5 Scarlet Ghouls with the device and return the ghouls to Gothik."},
	[12699] = {77, 77, "An Embarassing Incident", nil, nil, nil, nil, nil, nil, {12523}, {12671}, nil, nil, nil, nil, nil, nil, 12671, {77, 21400}, "Look for Vic's Keys inside the lake at River's Heart."},
	[12700] = {55, 55, "An Attack Of Opportunity", nil, nil, nil, nil, 32, nil, {12698}, {12701}, nil, nil, nil, nil, nil, nil, 12701, {55, 815}, "Speak with Prince Valanar at Death's Breach."},
	[12701] = {55, 55, "Massacre At Light's Point", nil, nil, nil, nil, 32, nil, {12700}, {12706}, nil, nil, nil, nil, nil, nil, 12706, {55, 16340}, "Prince Valanar at Death's Breach has commanded you to slaughter 100 Scarlet Defenders."},
