	[12708] = {77, 74, "Enchanted Tiki Warriors", nil, nil, nil, nil, nil, nil, {12685}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Element-Tamer Dagoda at Zim'Torga has asked you to destroy 12 Enchanted Tiki Warriors."},
	[12709] = {77, 74, "Hexed Caches", nil, nil, nil, nil, nil, nil, {12685}, nil, nil, nil, nil, nil, nil, nil, nil, {77, 21400}, "Chronicler To'kini at Zim'Torga has asked you to acquire 12 Zol'Maz Stronghold Caches."},
	[12710] = {75, 74, "Disclosure", nil, nil, nil, nil, nil, nil, {12690}, nil, nil, nil, nil, nil, nil, nil, nil, {75, 10500}, "Drakuru in Voltarus wants you to take the teleporter to his upper chamber."},
