	[12954] = {77, 75, "The Amphitheater of Anguish: Yggdras!", nil, nil, nil, nil, nil, nil, {9977}, {12932, 12933}, nil, nil, nil, nil, nil, nil, 12933, {77, 32100}, "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward."},
	[12955] = {80, 77, "Eliminate the Competition", nil, nil, nil, nil, nil, nil, {12938}, {12999}, nil, nil, nil, nil, nil, nil, 12999, {80, 22050}, "The Leaper at The Shadow Vault wants you to duel and defeat Sigrid Iceborn, Efrem the Faithful, Onu'zun and Tinky Wickwhistle.", {1098, 250}},
	[12956] = {80, 77, "A Spark of Hope", nil, nil, nil, nil, nil, nil, {12922}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 16550}, "You are to bring the Refined Gleaming Ore to Thorim in the Temple of Storms.", {1119, 250}},
	[12957] = {80, 77, "Slaves of the Stormforged", nil, nil, nil, nil, nil, nil, {12931}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to free 6 Captive Mechagnomes and kill 3 Stormforged Taskmasters."},
	[12958] = {-1, 65, "Shipment: Blood Jade Amulet", nil, 2, nil, nil, nil, nil, {13041}, {12959, 12960, 12961, 12962, 12963}, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 80}, "Combine a Vrykul Amulet, a Dark Jade and a Bloodstone to make a Blood Jade Amulet and bring it to Timothy Jones in Dalaran. You can find a Vrykul Amulet on any Northrend Vrykul.", {1090, 25}},
	[12959] = {-1, 65, "Shipment: Glowing Ivory Figurine", nil, 2, nil, nil, nil, nil, {13041}, {12958, 12960, 12961, 12962, 12963}, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 80}, "Combine Northern Ivory, a Chalcedony and a Shadow Crystal to create a Glowing Ivory Figurine and bring it to Timothy Jones in Dalaran. You can find a Northern Ivory on any Shoveltusk or Mammoth in Northrend.", {1090, 25}},
	[12960] = {-1, 65, "Shipment: Wicked Sun Brooch", nil, 2, nil, nil, nil, nil, {13041}, {12958, 12959, 12961, 12962, 12963}, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 80}, "Combine an Iron Dwarf Brooch, a Huge Citrine and a Sun Crystal to create a Wicked Sun Brooch and bring it to Timothy Jones in Dalaran. You can find an Iron Dwarf Brooch on any Northrend Iron Dwarf.", {1090, 25}},
	[12961] = {-1, 65, "Shipment: Intricate Bone Figurine", nil, 2, nil, nil, nil, nil, {13041}, {12958, 12959, 12960, 12962, 12963}, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 80}, "Combine a Proto Dragon Bone, a Sun Crystal and a Dark Jade to craft an Intricate Bone Figurine and bring it to Timothy Jones in Dalaran. You can find a Proto Dragon Bone on any Northrend Proto Dragon.", {1090, 25}},
	[12962] = {-1, 65, "Shipment: Bright Armor Relic", nil, 2, nil, nil, nil, nil, {13041}, {12958, 12959, 12960, 12961, 12963}, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 80}, "Combine an Elemental Armor Scrap, a Bloodstone and a Huge Citrine to craft a Bright Armor Relic and bring it to Timothy Jones in Dalaran. You can find an Elemental Armor Scrap on any Northrend Revenant.", {1090, 25}},
	[12963] = {-1, 65, "Shipment: Shifting Sun Curio", nil, 2, nil, nil, nil, nil, {13041}, {12958, 12959, 12960, 12961, 12962}, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 80}, "Combine a Scourge Curio, a Sun Crystal and a Shadow Crystal to make a Shifting Sun Curio and bring it to Timothy Jones in Dalaran. You can find a Scourge Curio on any Northrend Scourge.", {1090, 25}},
	[12964] = {80, 77, "The Dark Ore", nil, nil, nil, nil, nil, nil, {12931}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Bring 5 Ore Samples to Bouldercrag the Rockshaper at Bouldercrag's Refuge."},
	[12965] = {80, 77, "The Gifts of Loken", nil, nil, nil, nil, nil, nil, {12957}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Destroy Loken's Fury, Loken's Power, and Loken's Favor, and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge."},
	[12966] = {80, 77, "You Can't Miss Him", nil, nil, nil, nil, nil, {12915, 12956}, nil, {12967}, nil, nil, {1119, 0}, nil, nil, nil, 12967, nil, "King Jokkum in Dun Niffelem wants you to find Njormeld at Fjorn's Anvil.", {1119, 75}},
	[12967] = {80, 77, "Battling the Elements", nil, nil, nil, nil, nil, nil, {12966}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Njormeld wants you to accompany Snorri to Fjorn's anvil and help him kill 10 Seething Revenants.", {1119, 75}},
	[12968] = {80, 77, "Yulda's Folly", nil, nil, nil, nil, nil, nil, {12905}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 16550}, "Iva the Vengeful at Brunnhildar Village wants you to slay Yulda the Stormspeaker in Valkyrion."},
	[12969] = {80, 77, "Is That Your Goblin?", nil, nil, nil, nil, nil, nil, {12921}, {12970}, nil, nil, nil, nil, nil, nil, 12970, {80, 11050}, "Challenge Agnetta Tyrsdottar in order to save Zeev Fizzlespark. Return to Lok'lira the Crone in Brunnhildar Village after you've succeeded."},
	[12970] = {80, 77, "The Hyldsmeet", nil, nil, nil, nil, nil, nil, {12969}, {12971}, nil, nil, nil, nil, nil, nil, 12971, {80, 2200}, "Listen to Lok'lira the Crone's proposal."},
	[12971] = {80, 77, "Taking on All Challengers", nil, nil, nil, nil, nil, nil, {12970}, {12972}, nil, nil, nil, nil, nil, nil, 12972, {80, 22050}, "Lok'lira the Crone in Brunnhildar Village wants you to defeat 6 Victorious Challengers."},
	[12972] = {80, 77, "You'll Need a Bear", nil, nil, nil, nil, nil, nil, {12971}, {12851}, nil, nil, nil, nil, nil, nil, 12851, {80, 11050}, "Speak to Brijana outside Brunnhildar Village."},
	[12973] = {80, 77, "The Brothers Bronzebeard", 1, nil, nil, nil, nil, nil, {12880}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 33100}, "Accompany Brann Bronzebeard and his flying machine to Frosthold.", {1068, 500, 1126, 500}},
	[12974] = {77, 75, "The Champion's Call!", nil, nil, nil, nil, nil, nil, nil, {12932, 12954}, nil, nil, nil, nil, nil, nil, 12932, {77, 2150}, "Seek out Gurgthock at the Amphitheater of Anguish in Zul'Drak."},
	[12975] = {80, 77, "In Memoriam", nil, nil, nil, nil, nil, nil, {12924}, {12976}, nil, nil, nil, nil, nil, nil, 12976, {80, 22050}, "King Jokkum in Dun Niffelem wants you to collect 8 Horn Fragments from Thunderfall.", {1119, 250}},
	[12976] = {80, 77, "A Monument to the Fallen", nil, nil, nil, nil, nil, nil, {12975}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 11050}, "King Jokkum wants you to bring Hodir's Horn Fragments to Njormeld in Dun Niffelem.", {1119, 75}},
	[12977] = {80, 77, "Hodir's Call", nil, 2, nil, nil, nil, nil, {12976}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "You are to defeat 5 Niffelem Forefathers and 5 Restless Frostborn at Thunderfall. You are then to blow Hodir's Horn over their corpses, then return to Hodir's Horn in Dun Niffelem.", {1119, 350}},
	[12978] = {80, 77, "Facing the Storm", nil, nil, nil, nil, nil, nil, {12957}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Bruor Ironbane at Bouldercrag's Refuge wants you to kill 10 Nidavelir Stormforged. You may kill Stormforged Champions, Stormforged Magi, or Stormforged War Golems."},
	[12979] = {80, 77, "Armor of Darkness", nil, nil, nil, nil, nil, nil, nil, {12980}, nil, nil, nil, nil, nil, nil, 12980, {80, 22050}, "Bring 4 Dark Armor Samples to Bruor Ironbane at Bouldercrag's Refuge."},
	[12980] = {80, 77, "The Armor's Secrets", nil, nil, nil, nil, nil, nil, {12979}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Take the Dark Armor Plate to Mimir's Workshop and ask Attendant Tock to examine it. When you're finished, return to Bruor Ironbane at Bouldercrag's Refuge."},
	[12981] = {80, 77, "Hot and Cold", nil, 2, nil, nil, nil, nil, {12967}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "You are to go to Frostfield Lake, kill the Brittle Revenants there and use the Essence of Ice on the Smoldering Scraps at Fjorn's Anvil. You are then to collect 6 of the Frozen Iron scraps and return to Fjorn's Anvil in Dun Niffelem.", {1119, 350}},
	[12982] = {80, 77, "Ebon Blade Prisoners", nil, nil, nil, nil, nil, nil, {13085}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Vaelen the Flayed at The Shadow Vault wants you to free 8 Ebon Blade Prisoners. They can be found in the cages throughout the greater Jotunheim region.", {1098, 250}},
	[12983] = {80, 77, "The Last of Her Kind", nil, nil, nil, nil, nil, nil, {12900}, {12996}, nil, nil, nil, nil, nil, nil, 12996, {80, 22050}, "Astrid Bjornrittar in Brunnhildar Village wants you to rescue an Icemaw Matriarch in the Hibernal Cavern."},
	[12984] = {80, 77, "Valduran the Stormborn", nil, nil, nil, nil, nil, nil, {12980}, {12988}, nil, nil, nil, nil, nil, nil, 12988, {80, 27550}, "Use Bouldercrag's War Horn when you have found Valduran the Stormborn. Defeat Valduran the Stormborn and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge."},
	[12985] = {80, 77, "Forging a Head", nil, nil, nil, nil, nil, nil, nil, {12987}, nil, nil, {1119, 3000}, nil, nil, nil, 12987, {80, 22050}, "Njormeld in Dun Niffelem needs you to use the Diamond Tipped Pick on the Dead Iron Giants at Frostfield Lake and return to him when you have collected 8 Stormforged Eyes.", {1119, 250}},
	[12986] = {80, 77, "Fate of the Titans", 1, nil, nil, nil, nil, nil, {12877}, {12878}, nil, nil, nil, nil, nil, nil, 12878, {80, 22050}, "Creteus in the Foot Steppes has requested that you travel to the Temple of Invention, the Temple of Winter, the Temple of Life, and the Temple of Order and utilize the databank to examine each area."},
	[12987] = {80, 77, "Placing Hodir's Helm", nil, nil, nil, nil, nil, nil, {12985}, nil, nil, nil, {1119, 3000}, nil, nil, nil, nil, {80, 5500}, "Njormeld wants you to fly to the tip of the northern ice spike in Dun Niffelem and use the Tablets of Pronouncement.", {1119, 150}},
	[12988] = {80, 77, "Destroy the Forges!", nil, nil, nil, nil, nil, nil, {12984}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Destroy the North Lightning Forge, the Central Lightning Forge, and the South Lightning Forge with Bouldercrag's Bombs, then return to Bouldercrag the Rockshaper at Bouldercrag's Refuge."},
	[12989] = {80, 77, "The Slithering Darkness", nil, nil, nil, nil, nil, nil, {12900}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Astrid Bjornrittar wants you to slay 8 Ravenous Jormungar in the Hibernal Cavern east of Brunnhildar Village."},
	[12991] = {80, 77, "Hit Them Where it Hurts", nil, nil, nil, nil, nil, nil, {12984}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Kill 10 Stormforged Artificers and return to Bruor Ironbane at Bouldercrag's Refuge."},
	[12992] = {80, 77, "Crush Dem Vrykuls!", nil, nil, nil, nil, nil, nil, {12951}, {13071}, nil, nil, nil, nil, nil, nil, 13071, {80, 22050}, "Vile at The Shadow Vault wants you to slay any 15 vrykul in the greater Jotunheim region.", {1098, 250}},
	[12993] = {80, 77, "A Colossal Threat", nil, nil, nil, nil, nil, nil, {12988}, {12998}, nil, nil, nil, nil, nil, nil, 12998, {80, 22050}, "Retrieve the Colossus Attack Specs and Colossus Defense Specs and bring them to Bouldercrag the Rockshaper at Bouldercrag's Refuge."},
	[12994] = {80, 77, "Spy Hunter", nil, 2, nil, nil, nil, nil, nil, nil, nil, nil, {1119, 9000}, nil, nil, nil, nil, {80, 22050}, "You must defeat 3 Stormforged Spies in the Valley of Ancient Winters. Using the Ethereal Worg's Fang at the Corpse of the Fallen Worg will summon an Ethereal Frostworg, which will expose hidden enemies. You are to return to the Frostworg Denmother in Dun Niffelem when the valley has been cleansed of spies.", {1119, 350}},
	[12995] = {80, 77, "Leave Our Mark", nil, 2, nil, nil, nil, nil, {12951}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Baron Sliver at The Shadow Vault wishes you to plant 15 Ebon Blade Banners near the corpses of vrykul found within the greater Jotunheim region.", {1098, 250}},
	[12996] = {80, 77, "The Warm-Up", nil, nil, nil, nil, nil, nil, {12983}, {12997}, nil, nil, nil, nil, nil, nil, 12997, {80, 16550}, "Astrid Bjornrittar in Brunnhildar Village wants you to use the Reins of the Warbear Matriarch to defeat Kirgaraak."},
	[12997] = {80, 77, "Into the Pit", nil, nil, nil, nil, nil, nil, {12996}, {13061}, nil, nil, nil, nil, nil, nil, 13061, {80, 22050}, "Astrid Bjornrittar, in Brunnhildar Village, wants you to use the Reins of the Warbear Matriarch inside the Pit of the Fang and defeat 6 Hyldsmeet Warbears."},
	[12998] = {80, 77, "The Heart of the Storm", nil, nil, nil, nil, nil, nil, {12993}, {13007}, nil, nil, nil, nil, nil, nil, 13007, {80, 22050}, "Bouldercrag the Rockshaper at Bouldercrag's Refuge wants you to travel to Uldis and try to prevent Overseer Narvir from obtaining the Heart of the Storm."},
	[12999] = {80, 77, "The Bone Witch", nil, nil, nil, nil, nil, nil, {12955}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 2200}, "Speak with The Bone Witch within the cave at Njorndar Village.", {1098, 10}},
	[13000] = {79, 77, "Emergency Measures", 2, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {79, 21800}, "Bloodguard Lorga wants you to go to the Gimorak's Den to the east and obtain 6 Worg Furs.", {1085, 250}},
	[13001] = {80, 77, "Forging Hodir's Spear", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {1119, 9000}, nil, nil, nil, nil, {80, 22050}, "Lorekeeper Randvir in Dun Niffelem wants you to collect 3 Everfrost Shards from the depths of Hibernal Cavern and 3 Stoic Mammoth Hides from the Stoic Mammoths in the Valley of Ancient Winters.", {1119, 250}},
	[13003] = {80, 77, "How To Slay Your Dragon", nil, 2, nil, nil, nil, nil, {13001}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 27550}, "You are to use Hodir's Spear to challenge a Wild Wyrm in the Valley of Ancient Winters. Once in its grip, you are to fight to the death.", {1119, 500}},
	[13005] = {80, 77, "The Earthen Oath", nil, nil, nil, nil, nil, nil, {13057}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 27550}, "Thorim, at the Terrace of the Makers, wants you to use the Horn of the Peaks and call on the Earthen to defeat 20 Iron Dwarves and 7 Iron Sentinels."},
	[13006] = {80, 77, "A Viscous Cleaning", nil, 2, nil, nil, nil, nil, {12987}, nil, nil, nil, {1119, 3000}, nil, nil, nil, nil, {80, 22050}, "You are to enter Hibernal Cavern west of Dun Niffelem and collect 5 units of Viscous Oil from the Viscous Oils there. You are then to return to Dun Niffelem and apply the oil to Hodir's Helm.", {1119, 350}},
	[13007] = {80, 77, "The Iron Colossus", nil, nil, nil, nil, nil, nil, {12998}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 33100}, "Use a Tamed Jormungar to defeat the Iron Colossus and return to Bouldercrag the Rockshaper at Bouldercrag's Refuge."},
	[13008] = {78, 77, "Scourge Tactics", nil, nil, nil, nil, nil, nil, {13036}, nil, nil, nil, nil, nil, nil, nil, nil, {78, 21600}, "Crusade Commander Entari at the Argent Vanguard in Icecrown has asked that you free 8 Webbed Crusaders.", {1106, 250}},
	[13009] = {80, 77, "A New Beginning", nil, nil, nil, nil, nil, nil, {12924}, {13050}, nil, nil, nil, nil, nil, nil, 13050, {80, 22050}, "Njormeld wants you to take the Reforged Armor to Thorim at the Temple of Storms."},
	[13010] = {80, 77, "Krolmir, Hammer of Storms", nil, nil, nil, nil, nil, nil, {13051}, {13057}, nil, nil, nil, nil, nil, nil, 13057, {80, 27550}, "Thorim wants you to talk to King Jokkum in Dun Niffelem and discover what he knows of Krolmir.", {1119, 350}},
	[13011] = {80, 77, "Culling Jorcuttar", nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {1119, 3000}, nil, nil, nil, nil, {80, 22050}, "King Jokkum in Dun Niffelem wants you to slay Jorcuttar in Hibernal Cavern.", {1119, 250}},
	[13034] = {80, 77, "The Witness and the Hero", 2, nil, nil, nil, nil, nil, nil, {13037}, nil, nil, nil, nil, nil, nil, 13037, {80, 22050}, "Xarantaur, at Camp Tunka'lo, wants you to read the First History Scroll, the Second History Scroll, and the Third History Scroll.", {1085, 250}},
	[13035] = {80, 77, "Loken's Lackeys", nil, nil, nil, nil, nil, nil, {13057}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Thorim wants you to slay Eisenfaust inside the Hall of the Shaper and Halefnir the Windborn and Duronn the Runeforged in the Terrace of the Makers."},
	[13036] = {78, 77, "Honor Above All Else", nil, nil, nil, nil, nil, nil, {13226, 13227}, {13008}, nil, nil, nil, nil, nil, nil, 13008, {78, 2150}, "Report to Crusade Commander Entari at the Argent Vanguard in Icecrown.", {1037, 10}},
	[13037] = {80, 77, "Memories of Stormhoof", 2, nil, nil, nil, nil, nil, {13034}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Speak with Chieftain Swiftspear in Frostfloe Deep, then return to Xarantaur at Camp Tunka'lo.", {1085, 250}},
	[13038] = {80, 77, "Distortions in Time", 2, nil, nil, nil, nil, nil, {13034}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Use the Chieftain's Totem to close 4 Frostfloe Rifts, then bring the totem to Xarantaur at Camp Tunka'lo.", {1085, 250}},
	[13039] = {78, 77, "Defending The Vanguard", nil, nil, nil, nil, nil, nil, {13036}, nil, nil, nil, nil, nil, nil, nil, nil, {78, 21600}, "Crusader Lord Dalfors at the Argent Vanguard in Icecrown has asked that you kill 15 Forgotten Depths Nerubians.", {1106, 250}},
	[13040] = {78, 77, "Curing The Incurable", nil, nil, nil, nil, nil, nil, {13036}, nil, nil, nil, nil, nil, nil, nil, nil, {78, 21600}, "Father Gustav at the Argent Vanguard in Icecrown has asked that you bring him 10 Forgotten Depths Venom Sacs.", {1106, 250}},
	[13041] = {-1, 65, "Finish the Shipment", nil, nil, nil, nil, nil, nil, nil, nil, nil, {755, 375}, nil, nil, nil, nil, nil, {1, 40}, "Bring a Chalcedony to Timothy Jones in Dalaran."},
	[13042] = {80, 77, "Deep in the Bowels of The Underhalls", nil, nil, nil, nil, nil, nil, {12999}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "The Bone Witch in Njorndar Village has asked you to beat information out of Apprentice Osterkilgr concerning what Dr. Terrible is truly up to. You are then to slay the apprentice.", {1098, 250}},
	[13043] = {80, 77, "The Sum is Greater than the Parts", nil, nil, nil, nil, nil, nil, {12999}, {13091}, nil, nil, nil, nil, nil, nil, 13091, {80, 27550}, "Mount and take control of Nergeld. Defend it from the denizens of the Hall of Horrors until Dr. Terrible shows himself. Use Nergeld to slay the doctor, and then return to The Bone Witch in Njorndar Village.", {1098, 350}},
	[13044] = {78, 77, "If There Are Survivors...", nil, nil, nil, nil, nil, {13008, 13039, 13040}, nil, {13045}, nil, nil, nil, nil, nil, nil, 13045, {78, 2150}, "Speak with Penumbrius at the Argent Vanguard in Icecrown."},
	[13045] = {78, 77, "Into The Wild Green Yonder", nil, nil, nil, nil, nil, nil, {13044}, {13070}, nil, nil, nil, nil, nil, nil, 13070, {78, 27000}, "Rescue 3 Captured Argent Crusaders from Scourgeholme and drop them off at the Vanguard Infirmary at the center of the Argent Vanguard. Report to Highlord Tirion Fordring should you succeed.", {1106, 350}},
	[13046] = {80, 77, "Feeding Arngrim", nil, 2, nil, nil, nil, nil, nil, nil, nil, nil, {1119, 21000}, nil, nil, nil, nil, {80, 22050}, "You are to feed Arngrim 5 Disembodied Jormungar, then return to Arngrim's frozen image in Dun Niffelem. You must go to the Valley of Ancient Winters and use Arngrim's Tooth on the Roaming Jormungar there. Once they have become disembodied, you must fight them until they are weakened.", {1119, 350}},
	[13047] = {80, 77, "The Reckoning", nil, nil, nil, nil, nil, {13005, 13035}, nil, {13108}, nil, nil, nil, nil, nil, nil, 13108, {80, 33100}, "Meet Thorim near the Temple of Wisdom. Report the outcome of the fight to King Jokkum in Dun Niffelem."},
	[13048] = {80, 77, "Where Time Went Wrong", 2, nil, nil, nil, nil, {13037, 13038}, nil, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Use the Lorehammer on Taunka Relics to attune it to the time of Stormhoof. Once it has been attuned to 6 relics from the time of Stormhoof, return to Xarantaur at Camp Tunka'lo.", {1085, 250}},
	[13049] = {80, 77, "The Hero's Arms", 2, nil, nil, nil, nil, {13037, 13038}, nil, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Recover Stormhoof's Spear and Stormhoof's Mail and return them to Xarantaur at Camp Tunka'lo."},
	[13050] = {80, 77, "Veranus", nil, nil, nil, nil, nil, nil, {13009}, {13051}, nil, nil, nil, nil, nil, nil, 13051, {80, 22050}, "Thorim, at the Temple of Storms, wants you to obtain 5 Small Proto-Drake Eggs from the peaks near Brunnhildar Village."},
	[13051] = {80, 77, "Territorial Trespass", nil, nil, nil, nil, nil, nil, {13050}, {13010}, nil, nil, nil, nil, nil, nil, 13010, {80, 11050}, "Place the Stolen Proto-Dragon Eggs on top of the Broodmother's Nest and return to Thorim at the Temple of Storms."},
	[13054] = {80, 77, "The Missing Tracker", 2, nil, nil, nil, nil, nil, nil, {13055}, nil, nil, nil, nil, nil, nil, 13055, {80, 11050}, "Look for Tracker Val'zij inside Gimorak's Den, southeast of the Grom'arsh Crash Site.", {1085, 75}},
	[13055] = {80, 77, "Cave Medicine", 2, nil, nil, nil, nil, nil, {13054}, {13056}, nil, nil, nil, nil, nil, nil, 13056, {80, 22050}, "Tracker Val'zij, at Gimorak's Den, wants you to obtain 1 Jormungar Toxin Gland and 8 Cave Mushrooms."},
	[13056] = {80, 77, "There's Always Time for Revenge", 2, nil, nil, nil, nil, nil, {13055}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Tracker Val'zij wants you to slay Gimorak inside Gimorak's Den.", {1085, 250}},
	[13057] = {80, 77, "The Terrace of the Makers", nil, nil, nil, nil, nil, nil, {13010}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 11050}, "Find Thorim at the southeastern edge of the Terrace of the Makers, just northwest of Dun Niffelem."},
	[13058] = {80, 77, "Changing the Wind's Course", 2, nil, nil, nil, nil, {13048, 13049}, nil, nil, nil, nil, nil, nil, nil, nil, nil, {80, 27550}, "Use the Lorehammer to travel back in time and face the North Wind as Stormhoof. When Stormhoof falls and drops the Horn of Elemental Fury, use it to finish off the North Wind, and then return to Xarantaur at Camp Tunka'lo.", {1085, 350}},
	[13059] = {80, 77, "Revenge for the Vargul", nil, nil, nil, nil, nil, nil, {13092}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 27550}, "Bethod Feigr in The Underhalls wants you to throw down his sword to challenge Thane Illskar and then kill him in The Circle of Suffering.", {1098, 350}},
	[13060] = {78, 77, "When All Else Fails", 2, nil, nil, nil, nil, nil, {12824}, nil, nil, nil, nil, nil, nil, nil, nil, {78, 2150}, "Speak to Ricket to make use of Ricket's D16 Propelled Delivery Device to enter further into Storm Peaks."},
	[13061] = {79, 77, "Prepare for Glory", nil, nil, nil, nil, nil, nil, {12997}, {13062}, nil, nil, nil, nil, nil, nil, 13062, {79, 2200}, "Speak to Lok'lira the Crone in Brunnhildar Village."},
	[13062] = {80, 77, "Lok'lira's Parting Gift", nil, nil, nil, nil, nil, nil, {13061}, {12886}, nil, nil, nil, nil, nil, nil, 12886, {80, 5500}, "Speak to Gretta the Arbiter in Brunnhildar Village."},
	[13063] = {80, 77, "Deemed Worthy", nil, nil, nil, nil, nil, nil, {12856}, {12900}, nil, nil, nil, nil, nil, nil, 12900, {80, 11050}, "Brijana wants you to go to Brunnhildar Village and speak with Astrid Bjornrittar."},
	[13064] = {80, 77, "Sibling Rivalry", nil, nil, nil, nil, nil, nil, {12886}, {12915}, nil, nil, nil, nil, nil, nil, 12915, {80, 16550}, "Thorim wants you to listen to his story."},
	[13068] = {80, 77, "A Tale of Valor", nil, nil, nil, nil, nil, nil, {13141}, {13072}, nil, nil, nil, nil, nil, nil, 13072, {80, 2200}, "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you locate the hero, Crusader Bridenbrad at the Silent Vigil, in northeast Icecrown. His fire pit will likely be the most obvious indication of his location from the air.", {1106, 10}},
	[13069] = {80, 77, "Shoot 'Em Up", nil, 2, nil, nil, nil, nil, {12982}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "The Leaper at The Shadow Vault wants you to use a Jotunheim Rapid-Fire Harpoon to shoot down 15 Jotunheim Proto-Drakes and their riders.", {1098, 250}},
	[13070] = {78, 77, "A Cold Front Approaches", nil, nil, nil, nil, nil, nil, {13045}, {13086}, nil, nil, nil, nil, nil, nil, 13086, {78, 2150}, "Report to Siegemaster Fezzik at the Argent Vanguard in Icecrown.", {1106, 10}},
	[13071] = {80, 77, "Vile Like Fire!", nil, 2, nil, nil, nil, nil, {12992}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Vile at The Shadow Vault wants you to steal a Njorndar Proto-Drake and use it to set fire to 8 vrykul buildings in the greater Jotunheim region. Balargarde Fortress, due to its nature, cannot be set ablaze.", {1098, 250}},
	[13072] = {80, 77, "A Hero Remains", nil, nil, nil, nil, nil, nil, {13068}, {13073}, nil, nil, nil, nil, nil, nil, 13073, {80, 22050}, "Bring news of Crusader Bridenbrad's fate to Highlord Tirion Fordring at Crusaders' Pinnacle.", {1106, 250}},
	[13073] = {80, 77, "The Keeper's Favor", nil, nil, nil, nil, nil, nil, {13072}, {13074}, nil, nil, nil, nil, nil, nil, 13074, {80, 16550}, "Highlord Tirion Fordring at Crusaders' Pinnacle has requested that you secure passage from Arch Druid Lilliandra and speak to Keeper Remulos in Moonglade.", {1106, 150}},
	[13074] = {80, 77, "Hope Within the Emerald Nightmare", nil, nil, nil, nil, nil, nil, {13073}, {13075}, nil, nil, nil, nil, nil, nil, 13075, {80, 22050}, "Keeper Remulos at Moonglade has instructed you to enter the emerald dream and recover 3 Emerald Acorns. Leave the vicinity of the Shrine of Remulos to return to Azeroth."},
	[13075] = {80, 77, "The Boon of Remulos", nil, nil, nil, nil, nil, nil, {13074}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown with the Emerald Acorn.", {1106, 250}},
	[13076] = {80, 77, "Time Yet Remains", nil, nil, nil, nil, nil, nil, {13075}, {13077}, nil, nil, nil, nil, nil, nil, 13077, {80, 2200}, "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of Emerald Acorn's effects.", {1106, 10}},
	[13077] = {80, 77, "The Touch of an Aspect", nil, nil, nil, nil, nil, nil, {13076}, {13078}, nil, nil, nil, nil, nil, nil, 13078, {80, 16550}, "Request the aid of Alexstrasza the Life-Binder at Wyrmrest Temple.", {1106, 150}},
	[13078] = {80, 77, "Dahlia's Tears", nil, nil, nil, nil, nil, nil, {13077}, {13079}, nil, nil, nil, nil, nil, nil, 13079, {80, 22050}, "Alexstrasza the Life-Binder at Wyrmrest Temple has requested that you recover Dahlia's Tears from soil freshly cleansed by a Ruby Keeper's flames."},
	[13079] = {80, 77, "The Boon of Alexstrasza", nil, nil, nil, nil, nil, nil, {13078}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Bring the Breath of Alexstrasza to Crusader Bridenbrad at the Silent Vigil in Icecrown.", {1106, 250}},
	[13080] = {80, 77, "Hope Yet Remains", nil, nil, nil, nil, nil, nil, {13079}, {13081}, nil, nil, nil, nil, nil, nil, 13081, {80, 2200}, "Return to Highlord Tirion Fordring at Crusaders' Pinnacle with news of the effects of the Breath of Alexstrasza.", {1106, 10}},
	[13081] = {80, 77, "The Will of the Naaru", nil, nil, nil, nil, nil, nil, {13080}, {13082}, nil, nil, nil, nil, nil, nil, 13082, {80, 16550}, "Request the aid of A'dal at Shattrath City in Terokkar Forest.", {1106, 150}},
	[13082] = {80, 77, "The Boon of A'dal", nil, nil, nil, nil, nil, nil, {13081}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Return to Crusader Bridenbrad at the Silent Vigil in Icecrown.", {1106, 250}},
	[13083] = {80, 77, "Light Within the Darkness", nil, nil, nil, nil, nil, nil, {13082}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 33100}, "Bring Crusader Bridenbrad's Tabard to Highlord Tirion Fordring at Crusaders' Pinnacle.", {1106, 500}},
	[13084] = {80, 77, "Vandalizing Jotunheim", nil, nil, nil, nil, nil, nil, {12951}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "Duke Lankral at The Shadow Vault wants you to burn 10 Vrykul Banners.", {1098, 250}},
	[13085] = {80, 77, "Vaelen Has Returned", nil, nil, nil, nil, nil, nil, {12951}, {12982}, nil, nil, nil, nil, nil, nil, 12982, {80, 2200}, "Speak with Vaelen the Flayed at The Shadow Vault.", {1098, 10}},
	[13086] = {78, 77, "The Last Line Of Defense", nil, nil, nil, nil, nil, nil, {13070}, nil, nil, nil, nil, nil, nil, nil, nil, {78, 32400}, "Use an Argent Cannon to destroy 100 Scourge attackers. You must also kill 3 Frostbrood Destroyers. Return to Siegemaster Fezzik should you succeed.", {1106, 500}},
	[13087] = {-1, 65, "Northern Cooking", 1, nil, nil, nil, nil, nil, nil, {13088}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 40}, "Bring four chilled meat to Brom Brewbaster at Valgarde.  Chilled meat can be found on any Northrend beast.", {1050, 75}},
	[13088] = {-1, 65, "Northern Cooking", 1, nil, nil, nil, nil, nil, nil, {13087}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 40}, "Bring four chilled meat to Rollick Mackreel at Valiance Keep.  Chilled meat can be found on any Northrend beast.", {1050, 75}},
	[13089] = {-1, 65, "Northern Cooking", 2, nil, nil, nil, nil, nil, nil, {13090}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 40}, "Bring four chilled meat to Thomas Kolichio at Vengeance Landing.  Chilled meat can be found on any Northrend beast.", {1067, 75}},
	[13090] = {-1, 65, "Northern Cooking", 2, nil, nil, nil, nil, nil, nil, {13089}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 40}, "Bring four chilled meat to Orn Tenderhoof at Warsong Hold.  Chilled meat can be found on any Northrend beast.", {1085, 75}},
	[13091] = {80, 77, "The Art of Being a Water Terror", nil, nil, nil, nil, nil, nil, {13043}, {13121}, nil, nil, nil, nil, nil, nil, 13121, {80, 22050}, "The Bone Witch in Njorndar Village wants you to possess a Water Terror and use it to slay 10 vrykul in the greater Jotunheim region. Qualifying vrykul are Jotunheim Sleep-Watchers, Jotunheim Warriors, Mjordin Water Magi, Njorndar Spear-Sisters, and Valhalas Vargul.", {1098, 250}},
	[13092] = {80, 77, "Reading the Bones", nil, nil, nil, nil, nil, nil, {12999}, nil, nil, nil, nil, nil, nil, nil, nil, {80, 22050}, "The Bone Witch in Njorndar Village has instructed you to collect 15 Vrykul Bones.", {1098, 250}},
	[13093] = {80, 77, "Reading the Bones", nil, 3, nil, nil, nil, nil, {13092}, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, {1098, 10}},
	[13100] = {-1, 65, "Infused Mushroom Meatloaf", 1, 2, nil, nil, nil, nil, nil, {13101, 13102, 13103, 13107}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", {1090, 150}},
	[13101] = {-1, 65, "Convention at the Legerdemain", 1, 2, nil, nil, nil, nil, nil, {13100, 13102, 13103, 13107}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", {1090, 150}},
	[13102] = {-1, 65, "Sewer Stew", 1, 2, nil, nil, nil, nil, nil, {13100, 13101, 13103, 13107}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot. Once it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green.", {1090, 150}},
	[13103] = {-1, 65, "Cheese for Glowergold", 1, 2, nil, nil, nil, nil, nil, {13100, 13101, 13102, 13107}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Combine the empty cheese platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran. Bring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange.", {1090, 150}},
	[13104] = {78, 77, "Once More Unto The Breach, Hero", nil, nil, nil, nil, 1503, nil, {13086}, {13105}, nil, nil, nil, nil, nil, nil, nil, {78, 2150}, "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", {1098, 10, 1106, 10}},
	[13105] = {78, 77, "Once More Unto The Breach, Hero", nil, nil, nil, nil, 32, nil, {13086}, {13104}, nil, nil, nil, nil, nil, nil, nil, {78, 2150}, "Report to the Ebon Watcher in the Valley of Echoes just outside the Breach.", {1098, 10, 1106, 10}},
	[13106] = {80, 77, "Blackwatch", nil, nil, nil, nil, nil, nil, {12896, 12897}, {13119, 13120}, nil, nil, nil, nil, nil, nil, nil, {80, 2200}, "Speak to Darkrider Arly at Blackwatch in Icecrown.", {1098, 10}},
	[13107] = {-1, 65, "Mustard Dogs!", 1, 2, nil, nil, nil, nil, nil, {13100, 13101, 13102, 13103}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran. Bring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran.", {1090, 150}},
	[13110] = {78, 77, "The Restless Dead", nil, nil, nil, nil, nil, nil, {13104}, nil, nil, nil, nil, nil, nil, nil, nil, {78, 21600}, "Father Gustav at the Valley of Echoes in Icecrown wants you to use Holy Water on the corpses of Reanimated Crusaders to free 10 restless souls.", {1106, 250}},
	[13112] = {-1, 65, "Infused Mushroom Meatloaf", 2, 2, nil, nil, nil, nil, nil, {13113, 13114, 13115, 13116}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran.", {1090, 150}},
	[13113] = {-1, 65, "Convention at the Legerdemain", 2, 2, nil, nil, nil, nil, nil, {13112, 13114, 13115, 13116}, nil, {185, 350}, nil, nil, nil, nil, nil, {1, 60}, "Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran.", {1090, 150}},
